 $v=[];foreach(['titulo','cid_codigo','cid_descricao','inicio_afastamento','fim_afastamento','atividade_habitual','incapacidade_restricao','info_clinica','observacoes','conteudo_personalizado'] as $f)$v[$f]=trim($_POST[$f]??'');
 $dias=(int)($_POST['dias_afastamento']??0);$mid=(int)($_POST['modelo_id']??0);
 if(!$p)$err='Paciente inválido.';elseif(!$v['inicio_afastamento']||!$v['fim_afastamento']||$dias<1)$err='Informe início, fim e dias.';elseif(empty($_POST['confirmar']))$err='Confirme a revisão médica.';
 else{$code=unique_code('ATEST');$q=db()->prepare('INSERT INTO atestados(paciente_id,medico_id,atendimento_id,codigo_validacao,data_emissao,titulo,conteudo_personalizado,cid_codigo,cid_descricao,inicio_afastamento,fim_afastamento,dias_afastamento,atividade_habitual,incapacidade_restricao,info_clinica,observacoes,modelo_id,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$q->execute([$pid,$m['id'],$aid?:null,$code,date('Y-m-d H:i:s'),$v['titulo']?:'Atestado Médico',$v['conteudo_personalizado'],$v['cid_codigo'],$v['cid_descricao'],$v['inicio_afastamento'],$v['fim_afastamento'],$dias,$v['atividade_habitual'],$v['incapacidade_restricao'],$v['info_clinica'],$v['observacoes'],$mid?:null,'EMITIDO']);$id=db()->lastInsertId();db()->prepare('INSERT INTO documentos_versoes(tipo,documento_id,medico_id,versao,conteudo) VALUES(?,?,?,?,?)')->execute(['ATESTADO',$id,$m['id'],1,$v['conteudo_personalizado']]);audit_log('emitir_atestado','atestados',$id,['codigo'=>$code,'modelo_id'=>$mid]);header('Location:view.php?id='.$id);exit;}}
