<div><label>Título</label><input name="titulo" value="Atestado Médico"></div><div><label>Início *</label><input type="date" name="inicio_afastamento" required></div><div><label>Fim *</label><input type="date" name="fim_afastamento" required></div><div><label>Dias *</label><input type="number" name="dias_afastamento" min="1" required></div><div><label>Atividade habitual</label><input name="atividade_habitual" value="<?=e($pre['capacidade_atividades']??'')?>"></div></div></div>
